switch(start){
	case "@":
	    type = "bili_user";
	    break;
	case "#":
	case "＃":
	    type = "article"
	    break;
	case "%":
	    type = "video"
	    break
	case "&":
	    type = "live"
	    break;
	case "*":
	    type = "media_bangumi";
	    break;
	 case "?":
